-- 00_PRECHECK.sql — 클라우드 현재 상태 점검 (조회 전용 · 변경 없음)
-- 결과의 EXPECTED_MISSING 가 비어 있지 않은 객체 = 사내 보완분이 빠진 '수정 전 소스'.
-- CLOUD_ONLY_MARKERS 가 있으면 클라우드에만 있는 수정이 있다는 뜻 → 해당 객체 전체교체 전 반드시 알려 주세요.
SET PAGESIZE 200 LINESIZE 400 LONG 100000
COLUMN OBJECT_NAME FORMAT A36
COLUMN OBJECT_TYPE FORMAT A14
COLUMN EXPECTED_MISSING FORMAT A120
COLUMN CLOUD_ONLY_MARKERS FORMAT A80

-- PKG_DMF0014 PACKAGE
SELECT O.OBJECT_NAME, O.OBJECT_TYPE, O.STATUS, TO_CHAR(O.LAST_DDL_TIME,'YYYY-MM-DD HH24:MI:SS') LAST_DDL,
       (SELECT COUNT(*) FROM USER_SOURCE S WHERE S.NAME=O.OBJECT_NAME AND S.TYPE=O.OBJECT_TYPE) SRC_LINES,
       (SELECT LISTAGG(E.M, ',') WITHIN GROUP (ORDER BY E.M) FROM (SELECT COLUMN_VALUE M FROM TABLE(SYS.ODCIVARCHAR2LIST('E20260814-EXCELFORM'))) E
         WHERE E.M <> '-NONE-' AND NOT EXISTS (SELECT 1 FROM USER_SOURCE S WHERE S.NAME=O.OBJECT_NAME AND S.TYPE=O.OBJECT_TYPE AND INSTR(S.TEXT, E.M) > 0)) EXPECTED_MISSING,
       (SELECT LISTAGG(X.M, ',') WITHIN GROUP (ORDER BY X.M) FROM (SELECT DISTINCT REGEXP_SUBSTR(S.TEXT, 'E20[0-9]{6}-[A-Z0-9_]+') M FROM USER_SOURCE S
          WHERE S.NAME=O.OBJECT_NAME AND S.TYPE=O.OBJECT_TYPE AND REGEXP_LIKE(S.TEXT, 'E20[0-9]{6}-[A-Z0-9_]+')) X
         WHERE X.M NOT IN ('E20260814-EXCELFORM')) CLOUD_ONLY_MARKERS
  FROM USER_OBJECTS O WHERE O.OBJECT_NAME='PKG_DMF0014' AND O.OBJECT_TYPE='PACKAGE';

-- PKG_DMF0014 PACKAGE BODY
SELECT O.OBJECT_NAME, O.OBJECT_TYPE, O.STATUS, TO_CHAR(O.LAST_DDL_TIME,'YYYY-MM-DD HH24:MI:SS') LAST_DDL,
       (SELECT COUNT(*) FROM USER_SOURCE S WHERE S.NAME=O.OBJECT_NAME AND S.TYPE=O.OBJECT_TYPE) SRC_LINES,
       (SELECT LISTAGG(E.M, ',') WITHIN GROUP (ORDER BY E.M) FROM (SELECT COLUMN_VALUE M FROM TABLE(SYS.ODCIVARCHAR2LIST('E20230119-000186','E20230227-000456','E20240208-001344','E20241126-000426','E20260814-EXCELFORM','E20260818-BATCHKEEP','E20260818-GRAYWEEK','E20260818-MKTDEL','E20260818-MKTDISTINCT','E20260818-MKTMERGE','E20260818-MKTPKGUARD','E20260818-RAISE','E20260823-BUCKETNLS','E20260823-GRAYZERO','E20260827-EXCELFORM','E20260827-NLSDATE','E20260911-DMF0014ACC','E20260911-DMF0014FORM','E20260911-DMF0014MSG','E20260911-DMF0014MULTI','E20260915-DMF0014MSTCHK','E20260923-DMF0014VALMSG'))) E
         WHERE E.M <> '-NONE-' AND NOT EXISTS (SELECT 1 FROM USER_SOURCE S WHERE S.NAME=O.OBJECT_NAME AND S.TYPE=O.OBJECT_TYPE AND INSTR(S.TEXT, E.M) > 0)) EXPECTED_MISSING,
       (SELECT LISTAGG(X.M, ',') WITHIN GROUP (ORDER BY X.M) FROM (SELECT DISTINCT REGEXP_SUBSTR(S.TEXT, 'E20[0-9]{6}-[A-Z0-9_]+') M FROM USER_SOURCE S
          WHERE S.NAME=O.OBJECT_NAME AND S.TYPE=O.OBJECT_TYPE AND REGEXP_LIKE(S.TEXT, 'E20[0-9]{6}-[A-Z0-9_]+')) X
         WHERE X.M NOT IN ('E20230119-000186','E20230227-000456','E20240208-001344','E20241126-000426','E20260814-EXCELFORM','E20260818-BATCHKEEP','E20260818-GRAYWEEK','E20260818-MKTDEL','E20260818-MKTDISTINCT','E20260818-MKTMERGE','E20260818-MKTPKGUARD','E20260818-RAISE','E20260823-BUCKETNLS','E20260823-GRAYZERO','E20260827-EXCELFORM','E20260827-NLSDATE','E20260911-DMF0014ACC','E20260911-DMF0014FORM','E20260911-DMF0014MSG','E20260911-DMF0014MULTI','E20260915-DMF0014MSTCHK','E20260923-DMF0014VALMSG')) CLOUD_ONLY_MARKERS
  FROM USER_OBJECTS O WHERE O.OBJECT_NAME='PKG_DMF0014' AND O.OBJECT_TYPE='PACKAGE BODY';

-- SCM_ADM_EXCEL_COLUMNS DMF0014 — 사내 값과 다르면 DIFF_* = 'DIFF'
SELECT PROGRAM_ID, SHEET_NAME,
       CASE WHEN STORAGE_SQL_ID = 'PKG_DMF0014.P_DMF0014_CUST_FCST_EXCEL_UPLOAD' THEN 'SAME' ELSE 'DIFF' END DIFF_STORAGE_SQL_ID,
       CASE WHEN HEADER_CONTENT = 'Division*|Sales Site*|Plant Site*|Customer Project*|Customer Model*|Incoterms*|FCST Type*|Customs Handbook*|Measure Group*|Measure*|Upload UOM*|Project|Model' THEN 'SAME' ELSE 'DIFF' END DIFF_HEADER_CONTENT,
       OPTION_ATTRIBUTE_COLUMN_NUMBER, VALID_YN
  FROM SCM_MGR.SCM_ADM_EXCEL_COLUMNS WHERE PROGRAM_ID = 'DMF0014';

